WITH flattened_attrs AS (SELECT id, effective_from, tier_limits, tier_prices, ARRAY_MIN(tier_prices) AS lowest_price, SLICE(tier_limits, 1, 2) AS first_two_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers WHERE YEAR(effective_from) >= 2025) SELECT id, effective_from, tier_limits, tier_prices, lowest_price, first_two_limits, tier_revenue_caps, avg_tier_price, net_prices, LAG(avg_tier_price, 2) OVER (ORDER BY lowest_price, id) AS prev_avg_tier_price, LAG(lowest_price, 2) OVER (ORDER BY effective_from, id) AS prev_lowest_price, SUM(avg_tier_price) OVER (ORDER BY avg_tier_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_tier_price, ROW_NUMBER() OVER (ORDER BY lowest_price DESC, id) AS seq_no FROM flattened_attrs;
